    /// match at the start and end of the haystack.
    pub(crate) fn into_anchored(self) -> ConfiguredHIR {
        let hir = Hir::concat(vec![
            Hir::look(hir::Look::Start),
            self.hir,
            Hir::look(hir::Look::End),
        ]);
        ConfiguredHIR { config: self.config, hir }
    }

